import {createIndex,search,highlightTerms} from './search.js';
import {contextCases,contextCase} from './study.js';
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='research-interview-atlas-v1';
const labels={llmpros:'LLM-ProS',apros:'A-ProS',xlagent:'XLAgent',phd:'PhD direction',profile:'Your story',foundations:'Foundations',ask:'Ask the professor',engineering:'Engineering interviews',evident:'Evident & formal feedback',haonan:'Haonan Li interview',journey:'Research journey'};
const packCore=pack=>pack?.groups.flatMap(g=>g.questionIds)||[];
const colors={llmpros:'blue',apros:'green',xlagent:'orange'};
const defaults=()=>({saved:[],notes:{},ratings:{},checklist:{}});
let state=defaults(),storageAvailable=true;
try{const stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored&&typeof stored==='object'&&!Array.isArray(stored)){state={...defaults(),...stored};if(!Array.isArray(state.saved))state.saved=[];for(const k of ['notes','ratings','checklist'])if(!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))state[k]={};}}catch{storageAvailable=false;}
let data,index,lastPage='#home',currentView='home',limit=30,toastTimer,practice=null;
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageAvailable=false;toast('Browser storage is unavailable. Export your notes before leaving.');return false;}};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function stats(){const known=new Set(data.questions.map(q=>q.id));$('#nav-count').textContent=data.questions.length;$('#saved-count').textContent=state.saved.filter(id=>known.has(id)).length;}
function projectOptions(value='all'){return Object.entries({all:'All subjects',...labels}).map(([id,name])=>`<option value="${id}" ${value===id?'selected':''}>${name}</option>`).join('');}
function meta(q){return `<span class="badge ${colors[q.project]||''}">${esc(labels[q.project])}</span><span>${esc(q.topic)}</span><span>·</span><span>${esc(q.difficulty)}</span>${q.essential?'<span class="badge">Start here</span>':''}${state.ratings[q.id]==='confident'?'<span class="badge">Practiced</span>':''}`;}
function highlight(text,query){const terms=highlightTerms(query).filter(t=>t.length>1);if(!terms.length)return esc(text);const pattern=terms.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|');return String(text).split(new RegExp(`(${pattern})`,'gi')).map((part,i)=>i%2?`<mark>${esc(part)}</mark>`:esc(part)).join('');}
function card(q,query=''){const saved=state.saved.includes(q.id);let snippet=q.answer;if(query){const term=highlightTerms(query).find(t=>[...q.detail,q.caution].some(s=>s.toLowerCase().includes(t)));if(term&&!q.answer.toLowerCase().includes(term)){const source=[...q.detail,q.caution].find(s=>s.toLowerCase().includes(term));snippet=source;}}
return `<article class="q-card"><button class="save-star ${saved?'saved':''}" data-action="save" data-id="${q.id}" aria-label="${saved?'Unsave':'Save'} question" aria-pressed="${saved}">${saved?'★':'☆'}</button><div class="q-meta">${meta(q)}</div><button class="q-title" data-action="open" data-id="${q.id}">${highlight(q.question,query)}</button><p>${highlight(snippet,query)}</p><div class="q-actions"><button data-action="open" data-id="${q.id}">Read full answer & sources ↗</button><span class="q-tags">${q.tags.filter(t=>t!=='essential').slice(0,3).map(t=>esc(t)).join(' / ')}</span></div></article>`;}
function essentialRow(q,i){return `<button class="essential-row" data-action="open" data-id="${q.id}"><span class="row-number">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(q.question)}</strong><small>${esc(labels[q.project])} / ${esc(q.topic)}</small></span><span class="row-arrow">↗</span></button>`;}
function followupMarkup(q){if(!q.followups?.length)return '';return `<div class="answer-label">Be ready for the follow-up</div><ul>${q.followups.map(text=>{const target=data.questions.find(other=>other.question===text);return `<li>${target?`<button class="followup-link" data-action="open" data-id="${target.id}">${esc(text)} ↗</button>`:esc(text)}</li>`;}).join('')}</ul>`;}
function answerSections(q){return (q.answerSections||q.detail.map((body,i)=>({heading:`Explanation ${i+1}`,body}))).map((section,i)=>`<section class="answer-section"><h3><span class="answer-step" aria-hidden="true">${String(i+1).padStart(2,'0')}</span>${esc(section.heading)}</h3>${section.body.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('');}
function diagram(project){
 const c=project==='llmpros'?'#6288a5':project==='apros'?'#6e8b56':'#b58359';
 const start=`<svg viewBox="0 0 300 140" role="img" aria-label="${esc(labels[project])} conceptual process diagram"><defs><marker id="arrow-${project}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${c}"/></marker></defs>`;
 const line=(x1,y1,x2,y2,dash='')=>`<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="${c}" opacity=".7" stroke-dasharray="${dash}" marker-end="url(#arrow-${project})"/>`;
 const box=(x,y,w,label)=>`<rect x="${x}" y="${y}" width="${w}" height="32" rx="6" fill="#fffefa" stroke="${c}" stroke-opacity=".45"/><text x="${x+w/2}" y="${y+20}" text-anchor="middle" fill="${c}" font-family="system-ui" font-size="9">${label}</text>`;
 if(project==='llmpros')return start+line(70,70,110,70)+line(190,70,230,70)+box(12,54,62,'Problem')+box(110,54,80,'5 models')+box(229,54,60,'Judge')+`<text x="150" y="113" text-anchor="middle" fill="${c}" font-size="8" font-family="monospace">ONE ATTEMPT / MEASURE</text></svg>`;
 if(project==='apros')return start+line(89,58,124,58)+line(186,58,222,58)+`<path d="M253 76V103H53V76" fill="none" stroke="${c}" stroke-dasharray="3 3" marker-end="url(#arrow-${project})"/>`+box(20,42,69,'Generator')+box(123,42,64,'Judge')+box(220,42,64,'Critic')+`<text x="150" y="123" text-anchor="middle" fill="${c}" font-size="8" font-family="monospace">FEEDBACK + HISTORY</text></svg>`;
 return start+`<rect x="20" y="24" width="92" height="91" rx="8" fill="none" stroke="${c}" stroke-dasharray="3 3" opacity=".4"/><rect x="188" y="24" width="92" height="91" rx="8" fill="none" stroke="${c}" stroke-dasharray="3 3" opacity=".4"/>`+line(84,52,215,52)+line(84,87,215,87)+box(33,37,66,'Language A')+box(200,72,66,'Language B')+`<circle cx="150" cy="52" r="11" fill="#f7f2e8" stroke="${c}"/><circle cx="150" cy="87" r="11" fill="#f7f2e8" stroke="${c}"/><text x="150" y="127" text-anchor="middle" fill="${c}" font-size="8" font-family="monospace">TRACE THE INTERACTION</text></svg>`;
}
function home(){
 const selected=['profile-001','llmpros-006','apros-003','xlagent-033','phd-003'].map(id=>data.questions.find(q=>q.id===id)).filter(Boolean);
 // Select by question text for the final two, independent of content ordering.
 selected[3]=data.questions.find(q=>q.question==='What are the main repair results?');
 const confident=Object.values(state.ratings).filter(v=>v==='confident').length;
 return `<section class="hero"><div><div class="eyebrow">Your research, at your fingertips</div><h1>Know your work.<br><em>Own the conversation.</em></h1><p>Complete answers to the questions behind your papers, your contributions, and what comes next. Search, read the full explanation, and rehearse your next conversation.</p><div class="hero-actions"><a href="#library" class="button primary large">Explore the questions <span>↗</span></a><a href="#practice" class="button large">▷ Start a practice session</a></div></div><div class="orbit" aria-hidden="true"><div class="orbit-ring"></div><div class="orbit-ring second"></div><div class="orbit-core">ri</div><span class="orbit-chip one"><i class="dot blue"></i> MEASURE</span><span class="orbit-chip two"><i class="dot green"></i> REFINE</span><span class="orbit-chip three"><i class="dot orange"></i> CONNECT</span></div></section>
 <div class="stat-strip"><div class="stat"><strong>${data.questions.length}</strong><span>answered questions</span></div><div class="stat"><strong>03</strong><span>research projects</span></div><div class="stat"><strong>${data.glossary.length}</strong><span>concepts explained</span></div><div class="stat"><strong>${confident}</strong><span>answers practiced</span></div></div>
 <a class="pack-callout" href="#interview/evident"><span class="badge">Interview pack</span><strong>${esc(data.studyPacks?.[0]?.title||'')}</strong><span>${packCore(data.studyPacks?.[0]).length} prepared questions + backup answers + a caller-context exercise ↗</span></a><a class="pack-callout" href="#journey"><span class="badge">Asked by every professor</span><strong>Explain what you did</strong><span>${data.questions.filter(q=>q.project==='journey').length} full speeches, from one minute to about seven ↗</span></a>
 <section><div class="section-head"><div><h2>Three projects. One research journey.</h2><p>From measuring capability to building reliable software agents.</p></div><a href="#sources" class="text-link">About the evidence ↗</a></div><div class="project-grid">${data.projects.map(p=>`<a href="#project/${p.id}" class="project-card"><div class="card-visual ${p.color}">${diagram(p.id)}</div><div class="card-body"><div class="eyebrow">${p.eyebrow}</div><h3>${p.name}</h3><span class="venue">${p.venue}</span><p>${esc(p.title)} ${p.id==='llmpros'?'Five models. A first-attempt benchmark.':p.id==='apros'?'Execution feedback with persistent context.':'Localization and repair across languages.'}</p><div class="card-foot"><span>${data.questions.filter(q=>q.project===p.id).length} questions to explore</span><span>↗</span></div></div></a>`).join('')}</div></section>
 <div class="home-bottom"><section><div class="section-head"><div><h2>Start with the essentials</h2><p>The questions you should be able to answer out loud.</p></div></div><div class="essential-list">${selected.map(essentialRow).join('')}</div><a href="#library?essential=1" class="text-link" style="display:inline-block;margin-top:14px">See every essential question ↗</a></section><aside class="note-card"><div class="eyebrow">A better conversation</div><h3>The interview goes<br>both ways.</h3><p>Research fit, funding, supervision, lab culture and what a good first year looks like. Prepare questions that help you choose, too.</p><a href="#ask" class="button">Questions for professors ↗</a><div class="source-mini">Every question includes a complete structured answer with evidence and limitations. Future research plans are clearly labeled.</div></aside></div>
 <section class="panel" style="margin-top:35px"><h2>Your pre-interview checklist</h2><p>Small preparations that make a clear conversation possible. Saved only in this browser.</p><div class="checklist">${['Practice a one-minute introduction','Explain my contribution to each project','Recall the main results and denominators','Prepare one limitation and next experiment','Read one recent paper from the lab','Choose three questions for the professor'].map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checklist[i]?'checked':''}>${s}</label>`).join('')}</div></section>`;
}
function library(view,params){
 const isAsk=view==='ask',saved=view==='saved',value=params.get('q')||'';
 const title=isAsk?'Make it a two-way conversation.':saved?'Your questions, collected.':'Every question is a way in.';
 const desc=isAsk?'Questions to ask about research fit, funding, supervision and the day-to-day experience of a PhD. Choose the ones that matter for this meeting.':saved?'Build a focused collection for your next meeting. Your stars and notes stay in this browser.':'Search complete answers, technical explanations, examples and results. Each question has a concise answer and a full structured version to practise aloud.';
 const topic=params.get('topic')||'all',project=isAsk?'ask':params.get('project')||'all';
 return `<div class="page-heading"><div class="eyebrow">${isAsk?'Beyond your answers':saved?'Your study collection':'The question library'}</div><h1>${title}</h1><p>${desc}</p></div><div class="search-box"><span aria-hidden="true">⌕</span><input id="library-search" type="search" value="${esc(value)}" placeholder="Try: memory, my contribution, leakage, funding…" aria-label="Search questions and answers" autocomplete="off"><button data-action="clear-search" aria-label="Clear search">×</button><kbd>/</kbd></div><p class="search-help">All keywords must match. Use “quoted phrases” for exact phrases and -word to exclude. Related terms and small typos work too.</p><div class="filters">${isAsk?'':`<select id="project-filter" aria-label="Filter by subject">${projectOptions(project)}</select>`}<select id="topic-filter" aria-label="Filter by topic"><option value="all">All topics</option>${[...new Set(data.questions.filter(q=>project==='all'||q.project===project).map(q=>q.topic))].sort().map(t=>`<option ${t===topic?'selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select><select id="difficulty-filter" aria-label="Filter by depth"><option value="all">Every depth</option>${['Core','Technical','Challenge'].map(d=>`<option ${params.get('difficulty')===d?'selected':''}>${d}</option>`).join('')}</select><label><input id="essential-filter" type="checkbox" ${params.get('essential')==='1'?'checked':''}> Essentials only</label><button class="button subtle" data-action="reset-filters">Reset</button></div><div class="results-bar" aria-live="polite"><span id="result-count"></span><span id="search-time"></span></div><div id="results" class="question-list"></div><div id="more" class="load-more"></div>${saved?'<p class="settings-note">Use Sources & accuracy to export or import your private study data.</p>':''}`;
}
function updateResults(reset=true){
 if(!$('#library-search'))return;
 if(reset)limit=30;
 const q=$('#library-search').value,project=currentView==='ask'?'ask':$('#project-filter')?.value||'all',topic=$('#topic-filter').value,difficulty=$('#difficulty-filter').value,essential=$('#essential-filter').checked;
 const start=performance.now(),hits=search(index,q,{project,topic,difficulty,essential,saved:currentView==='saved'?new Set(state.saved):null}),elapsed=performance.now()-start;
 $('#result-count').innerHTML=`<strong>${hits.length}</strong> ${hits.length===1?'question':'questions'}${q?` for “${esc(q)}”`:''}`;
 $('#search-time').textContent=q?`Found in ${Math.max(1,Math.round(elapsed))} ms`:'Search your research';
 $('#results').innerHTML=hits.length?hits.slice(0,limit).map(h=>card(h.question,q)).join(''):`<div class="empty"><h3>${currentView==='saved'&&!q?'A collection starts with one question.':'No questions match yet.'}</h3><p>${currentView==='saved'&&!q?'Tap ☆ on any question to save it here.':'Try fewer keywords, a related concept, or clear the filters.'}</p><a class="button" href="#library">Explore all questions ↗</a></div>`;
 $('#more').innerHTML=hits.length>limit?`<button class="button" data-action="more">Show ${Math.min(30,hits.length-limit)} more questions</button>`:'';
 const params=new URLSearchParams();if(q)params.set('q',q);if(project!=='all'&&currentView!=='ask')params.set('project',project);if(topic!=='all')params.set('topic',topic);if(difficulty!=='all')params.set('difficulty',difficulty);if(essential)params.set('essential','1');
 const route=`#${currentView}${params.size?'?'+params:''}`;history.replaceState(null,'',route);lastPage=route;
}
const speechWords=q=>q.answerSections.reduce((n,s)=>n+s.body.split(/\s+/).length,0);
const speechMinutes=q=>{const m=Math.max(1,Math.round(speechWords(q)/130));return `About ${m} minute${m>1?'s':''}`;};
function speechReader(q){const s=data.sources.find(s=>s.id===q.source);return `<div class="speech-meta"><span class="badge">${speechMinutes(q)} aloud</span><span>${speechWords(q)} words</span></div><h2>${esc(q.question)}</h2><p class="speech-cue"><strong>Use this when they say:</strong> ${esc(q.speech.cue)}</p><details class="short-answer"><summary>Short answer for quick recall</summary><p class="spoken">${esc(q.answer)}</p></details><div class="answer-label">Full speech. The headings are only for you, so do not read them aloud.</div><div class="full-answer speech-text">${answerSections(q)}</div><div class="caution"><strong>Stay accurate</strong>${esc(q.caution)}</div><p class="source-evidence"><span class="badge">${esc(s.kind)}</span><br>${esc(q.locator)}</p><div class="dialog-actions"><button class="button" data-action="copy" data-id="${q.id}">Copy speech</button><button class="button" data-action="open" data-id="${q.id}">Save or add notes ↗</button></div>`;}
function journeyView(id){const speeches=data.questions.filter(q=>q.project==='journey'),current=speeches.find(q=>q.id===id)||speeches[0];return `<div class="page-heading"><div class="eyebrow">Your research journey</div><h1>Explain what you did.</h1><p>Professors often ask you to describe your work in your own words. These are complete speeches in simple spoken English, from one minute to about seven. If you are not sure which one to use, start with the two-minute version and let the professor ask for more.</p><div class="hero-actions"><button class="button primary" data-action="practice-project" data-project="journey">▷ Practice these speeches</button><button class="button" data-action="speech" data-id="journey-002">Open the two-minute version</button></div></div><div class="speech-layout"><nav class="speech-menu" aria-label="Choose a speech">${[...new Set(speeches.map(q=>q.topic))].map(topic=>`<div class="speech-group"><h2>${esc(topic)}</h2>${speeches.filter(q=>q.topic===topic).map(q=>`<button class="speech-choice" data-action="speech" data-id="${q.id}" aria-pressed="${q.id===current.id}"><strong>${esc(q.speech.label)}</strong><small>${speechMinutes(q).replace('About ','')}</small></button>`).join('')}</div>`).join('')}</nav><article id="speech-reader" class="speech-reader" tabindex="-1">${speechReader(current)}</article></div>`;}
function selectSpeech(id){const q=data.questions.find(q=>q.id===id),reader=$('#speech-reader');if(!q||!reader)return;reader.innerHTML=speechReader(q);$$('.speech-choice').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)));const route=`#journey/${id}`;history.replaceState(null,'',route);lastPage=route;reader.scrollIntoView({block:'start'});reader.focus({preventScroll:true});}
function studyPackView(id){
 const pack=data.studyPacks?.find(p=>p.id===id);if(!pack)return '<div class="empty"><h3>Study pack not found.</h3><a class="button" href="#home">Return to overview</a></div>';
 return `<div class="page-heading"><div class="eyebrow">A separate reading & rehearsal path</div><h1>${esc(pack.title)}</h1><p>${esc(pack.description)}</p><div class="hero-actions"><button class="button primary" data-action="practice-pack" data-pack="${pack.id}">▷ Rehearse this pack</button><button class="button" data-action="jump-pack">Go to the ${packCore(pack).length} prepared questions ↓</button><a class="button subtle" href="#journey">Your research journey ↗</a><a class="button subtle" href="#library?project=evident">All Evident questions ↗</a></div></div>
 <section><div class="section-head"><div><h2>A 60-minute rehearsal.</h2><p>A suggested allocation, not a meeting schedule or a claim about anyone's interview plan.</p></div></div><div class="pack-agenda">${pack.groups.map((g,i)=>`<article><span>${String(i+1).padStart(2,'0')} / ${g.minutes} MIN</span><h3>${esc(g.title)}</h3><small>${g.questionIds.length} complete answers</small></article>`).join('')}</div></section>
 <section id="pack-questions"><div class="section-head"><div><h2>The prepared questions</h2><p>Every entry opens a complete structured response. Search covers these answers and the deeper backup below them.</p></div></div><div class="search-box"><span aria-hidden="true">⌕</span><input id="pack-search" type="search" aria-label="Search this study pack" placeholder="Try: title, judge, caller, proof, contribution…" autocomplete="off"></div><div id="pack-result-count" class="results-bar" aria-live="polite" style="margin-top:17px"></div><div id="pack-results" data-pack="${pack.id}"></div></section>
 <div class="pack-key-points"><article><span>01 / Defend the title</span><h3>Turn adjectives into claims.</h3><p>Towards means partial progress. Reliable needs a measure. Autonomous needs a boundary. Programming is the evaluated scope.</p><button data-action="open" data-id="apros-036" class="text-link">Read the complete title answer ↗</button></article><article><span>02 / Interpret the evidence</span><h3>A verdict is not an alarm.</h3><p>A failed judge case is an observed outcome. A conservative alarm may reflect lost information without a feasible counterexample.</p><button data-action="open" data-id="evident-005" class="text-link">Read the comparison answer ↗</button></article><article><span>03 / Narrow the proposal</span><h3>Recover source context.</h3><p>Existing validation repair is the baseline. Test original caller context after an accepted-but-alarmed harness, with safety controls.</p><button data-action="open" data-id="evident-020" class="text-link">Read the proposed experiment ↗</button></article></div>
 <section class="panel" style="margin-top:24px"><h2>The distinction to understand first</h2>${table(['Question','Online judge','Eva / static analysis'],[['What is inspected?','Candidate executions on a test suite.','A model of sets of program behaviors.'],['What does failure mean?','Observed rejection under that setup; infrastructure still needs attribution.','The property was not established; an alarm need not be a feasible bug.'],['What does success establish?','Acceptance for the scored tests and limits.','A harness-relative conclusion under the analysis and modeling assumptions.'],['What can go wrong?','Incomplete tests, wrong setup, leaked answers.','Imprecision, missing models, or a harness that omits original behavior.'],['What should change next?','Investigate and revise a candidate using the actual failure.','Diagnose context, models and precision before refining; retain uncertainty.']])}<p class="footnote">Shared lesson: evaluate the evidence boundary. The two feedback types do not support an identical revision rule.</p></section>
 <section class="panel" style="margin-top:24px"><h2>Existing mechanism and proposed boundary</h2><div class="architecture-wrap" tabindex="0" aria-label="Scrollable Evident workflow diagram"><img class="architecture-image" src="./assets/evident-workflow.svg" alt="Existing construction and validation repair precedes backend analysis. A proposed, untested outer loop recovers original caller context after an accepted harness still alarms."></div><div class="info-strip">The paper already describes harness repair and a precision cascade. The dashed outer loop is a hypothesis to compare with the actual implementation, not a verified missing feature or established improvement.</div><p class="flow-caption">The original program, support layer, validation and relevant budgets remain fixed. No invented constraints and no discarded unsafe contexts.</p></section>
 <section class="panel" style="margin-top:24px"><div class="section-head" style="margin-top:0"><div><h2>Work through the caller example.</h2><p>Change one assumption and see why the conclusion changes.</p></div><span class="badge orange">Synthetic thought experiment</span></div><label class="case-select-label" for="context-case">Original caller and represented context</label><select id="context-case" class="case-select">${contextCases.map(c=>`<option value="${c.id}">${c.label}</option>`).join('')}</select><div id="context-result"></div><p class="footnote">This explains source-level logic. It does not run Eva, Evident or a kernel benchmark. Concrete sample tests cannot establish universal safety.</p></section>
 <section class="panel" style="margin-top:24px"><h2>Keep versions and denominators separate.</h2>${table(['Reading','Outcome to remember','Boundary'],[['Earlier evaluation','151 correct / 200; 111 false alarms filtered.','Historical figures. Residual cases were not all validation failures.'],['Revised primary evaluation','102 / 160 false alarms filtered; 40 confirmed bugs retained.','57 false alarms retained after analysis, one false alarm unresolved.'],['Filtering rate','102 / 160 = 63.8%.','Not 102 / 200; that is workload reduction of 51.0%.'],['Safety observation','No confirmed bug dismissed in the tested set.','An empirical result, not an end-to-end soundness theorem.']])}<p class="footnote">Use the versioned paper, not a summary page that may still describe the earlier evaluation. Revised failure causes overlap rather than form a disjoint partition.</p></section>
 <section class="panel" style="margin-top:24px"><h2>Read against the primary sources.</h2><div class="pack-references">${pack.references.map(ref=>`<a href="${ref.url}" class="inline-link" target="_blank" rel="noopener noreferrer">${esc(ref.title)} ↗</a>`).join('')}</div><p class="footnote">Thread-specific scheduling, correspondence and meeting links stay outside this public guide. Publication status was checked separately from the frozen experimental snapshot.</p></section>`;
}
function renderContextCase(){const el=$('#context-result');if(!el)return;const c=contextCase($('#context-case').value);el.innerHTML=`<div class="context-code-grid"><div><div class="mini-heading">Original toy source</div><pre><code>${esc(c.original)}</code></pre></div><div><div class="mini-heading">Proposed harness context</div><pre><code>${esc(c.harness)}</code></pre></div></div><div class="case-decision ${c.tone}"><strong>${esc(c.status)}</strong><p>${esc(c.explanation)}</p><p>${esc(c.boundary)}</p></div>`;}
function renderPackQuestions(){const el=$('#pack-results');if(!el)return;const pack=data.studyPacks.find(p=>p.id===el.dataset.pack),query=$('#pack-search').value;const hits=search(index,query,{saved:new Set(pack.questionIds)});$('#pack-result-count').innerHTML=`<span><strong>${hits.length}</strong> of ${pack.questionIds.length} selected questions</span><span>Full explanations, not drafting instructions</span>`;if(query){el.innerHTML=hits.length?`<div class="question-list">${hits.map(h=>card(h.question,query)).join('')}</div>`:'<div class="empty"><h3>No matches in this pack.</h3><p>Try one or two keywords.</p></div>';return;}let n=0;const groupHtml=(group,rank)=>`<section class="pack-question-group"><h3>${esc(group.title)}</h3><div class="essential-list">${group.questionIds.map((id,i)=>essentialRow(data.questions.find(q=>q.id===id),rank?rank():i)).join('')}</div></section>`;el.innerHTML=pack.groups.map(group=>groupHtml(group,()=>n++)).join('')+(pack.backupGroups?.length?`<div class="section-head"><div><h2>Deeper backup answers</h2><p>The earlier Evident study answers, for going further on any topic.</p></div></div>${pack.backupGroups.map(group=>groupHtml(group)).join('')}`:'');}

function projectView(id){const p=data.projects.find(p=>p.id===id);if(!p)return '<div class="empty"><h3>Project not found.</h3><a href="#home">Return to overview</a></div>';
 const questions=data.questions.filter(q=>q.project===id&&q.essential).slice(0,5);
 return `<section class="project-hero"><div><div class="eyebrow">${p.eyebrow}</div><h1>${p.name}</h1><span class="badge ${p.color}">${p.status}</span> <span class="venue">${p.venue}</span><p style="margin-top:18px">${p.summary}</p></div><div class="card-visual ${p.color}">${diagram(id)}</div></section><div class="project-stats">${p.metrics.map(m=>`<div class="metric-card"><strong>${m.value}</strong><small>${m.label}</small></div>`).join('')}</div><div class="two-col"><section class="panel"><div class="eyebrow">Short answer</div><h2 style="margin-top:13px">Explain it in a minute.</h2><p>${p.pitch}</p><button class="button" data-action="practice-project" data-project="${id}">▷ Practice this project</button></section><section class="panel"><h2>What I contributed</h2><ul>${p.ownership.map(s=>`<li>${s}</li>`).join('')}</ul><p class="footnote">Ownership comes from the author record. Use your own concrete examples when speaking.</p></section></div><section class="panel" style="margin-top:20px"><h2>How the work fits together</h2><div class="architecture-wrap" tabindex="0" aria-label="Scrollable architecture diagram"><img class="architecture-image" src="./assets/${id}-architecture.svg" alt="${p.name} architecture: ${p.flow.join(' to ')}. See the step summary below."></div><div class="flow" aria-label="${p.name} pipeline">${p.flow.map((step,i)=>`${i?'<span class="flow-arrow" aria-hidden="true">→</span>':''}<div class="flow-step"><small>STEP 0${i+1}</small>${step}</div>`).join('')}</div><p class="flow-caption">${id==='apros'?'Feedback loops from the critic back to generation, stopping on acceptance or after four submissions.':id==='xlagent'?'Visible test feedback can return to investigation. Hidden scoring stays outside the agent loop.':'A first-attempt measurement pipeline with no judge-driven revision.'}</p></section><section class="panel" style="margin-top:20px"><h2>The result and its boundary</h2><p>${p.finding}</p><div class="caution"><strong>Scope & limitations</strong>${p.caution}</div>${id==='apros'?aprosTable():id==='xlagent'?xlTable():llmTable()}<p class="footnote">Source: ${esc(data.sources.find(s=>s.id===p.source).title)}. Reported results, not independently reproduced experiments.</p></section><div class="section-head"><div><h2>Questions to be ready for</h2><p>${p.next}</p></div><a href="#library?project=${id}" class="text-link">All ${data.questions.filter(q=>q.project===id).length} questions ↗</a></div><div class="question-list">${questions.map(q=>card(q)).join('')}</div>`;
}
function table(headers,rows){return `<div class="table-scroll"><table class="claim-table"><thead><tr>${headers.map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function llmTable(){return table(['Model','Accepted / 166','Rate'],[['o1-mini','16','9.64%'],['o1-preview','15','9.04%'],['GPT-4o','0','0%'],['Mistral Large','0','0%'],['Llama-3.1-405B','0','0%']]);}
function aprosTable(){return table(['Comparison','Observed count','Interpretation'],[['GPT-5 / ICPC (167)','39 → 85-90','Three feedback rounds; not the 367-task total.'],['GPT-4 / ICPC (167)','15 → 31-38','Same four-submission maximum.'],['Memory / GPT-5 (47)','19 vs 14','+10.6 percentage points; raw p = 0.063.'],['Memory / GPT-4 (47)','12 vs 8','+8.5 percentage points; raw p = 0.125.']]);}
function xlTable(){return table(['Measure','Current result','Interpretation'],[['Strict corpus','31 of 86','Fix requires interacting source changes on both sides.'],['In-scope graph coverage','11 of 12','Across all indexed strict fixes: 13 of 30.'],['Shell localization','12 of 12','No measurable graph benefit.'],['Two-sided developer-file edits','4.0 vs 2.7 of 5','Full vs baseline, mean of three replicates.'],['Fully correct patches / LLM judges','3 vs 4 of 15','No correctness advantage. Author review is stricter.']]);}
function practiceView(){return `<div class="page-heading"><div class="eyebrow">The practice room</div><h1>Find the words. Then say them.</h1><p>Read the prompt, answer out loud, then reveal the evidence. Rate your confidence to build a review list. Your timer is a guide, not a score.</p></div><div class="practice-controls"><select id="practice-project" aria-label="Practice subject">${projectOptions(practice?.project||'all')}</select><select id="practice-mode" aria-label="Practice selection">${[['essential','Essentials'],['all','All questions'],['saved','Saved questions'],['review','Needs practice'],...(data.studyPacks||[]).map(p=>['pack:'+p.id,p.title])].map(([v,s])=>`<option value="${v}" ${practice?.mode===v?'selected':''}>${s}</option>`).join('')}</select><select id="practice-size" aria-label="Session length">${[5,10,20,30].map(n=>`<option value="${n}" ${(practice?.size||10)===n?'selected':''}>${n} questions</option>`).join('')}</select><button class="button primary" data-action="start-practice">Start new session ↗</button></div><div id="practice-stage" class="practice-stage"></div>`;}
function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function startPractice(){const project=$('#practice-project').value,mode=$('#practice-mode').value,size=Number($('#practice-size').value);let pool=data.questions.filter(q=>project==='all'||q.project===project);if(mode==='essential')pool=pool.filter(q=>q.essential);if(mode==='saved')pool=pool.filter(q=>state.saved.includes(q.id));if(mode==='review')pool=pool.filter(q=>state.ratings[q.id]==='again');if(mode.startsWith('pack:')){const ids=new Set(packCore(data.studyPacks?.find(p=>p.id===mode.slice(5))));pool=pool.filter(q=>ids.has(q.id));}practice={project,mode,size,deck:shuffle(pool).slice(0,size),pos:0,revealed:false,start:Date.now(),elapsed:0,results:[]};renderPractice();}
function renderPractice(){const el=$('#practice-stage');if(!el)return;if(!practice?.deck){el.innerHTML=`<div class="empty"><h3>A little rehearsal goes a long way.</h3><p>Start with 10 essential questions, or choose a project to go deeper.</p><button class="button primary" data-action="start-practice">▷ Begin practice</button></div>`;return;}
 if(!practice.deck.length){el.innerHTML=`<div class="empty"><h3>No questions in this selection.</h3><p>${practice.mode==='saved'?'Save a few questions first.':practice.mode==='review'?'Rate an answer “Needs practice” to put it in this deck.':'Try a different subject or selection.'}</p><a class="button" href="#library">Explore the library ↗</a></div>`;return;}
 if(practice.pos>=practice.deck.length){const again=practice.results.filter(x=>x==='again').length;el.innerHTML=`<div class="practice-card"><div class="eyebrow">Session complete</div><h2>You made room for ${practice.deck.length} better answers.</h2><p class="muted">${again} marked for another look. ${practice.results.filter(x=>x==='confident').length} marked confident. Confidence is your self-assessment, not a correctness score.</p><div class="practice-footer"><button class="button primary" data-action="start-practice">Practice again ↗</button><a class="button" href="#saved">Your saved questions</a></div></div>`;return;}
 const q=practice.deck[practice.pos];
 el.innerHTML=`<div class="practice-top"><span>QUESTION ${String(practice.pos+1).padStart(2,'0')} / ${String(practice.deck.length).padStart(2,'0')}</span><span class="timer" id="practice-timer">${formatTime(practice.revealed?practice.elapsed:Date.now()-practice.start)}</span></div><div class="progress-track"><div style="width:${practice.pos/practice.deck.length*100}%"></div></div><article class="practice-card"><div class="q-meta">${meta(q)}</div><h2>${esc(q.question)}</h2>${practice.revealed?`<div class="practice-answer"><details class="short-answer"><summary>Short answer for quick recall</summary><p>${esc(q.answer)}</p></details><div class="answer-label">${q.project==='ask'?'Complete conversation script':'Complete practice answer'}</div><div class="full-answer">${answerSections(q)}</div>${q.caution?`<div class="caution"><strong>Scope & limitations</strong>${esc(q.caution)}</div>`:''}<p class="source-mini">${esc(data.sources.find(s=>s.id===q.source).title)} / ${esc(q.locator)}</p><div class="practice-rating"><button class="button" data-action="rate" data-rating="again">↻ Needs practice</button><button class="button primary" data-action="rate" data-rating="confident">✓ Feeling confident</button></div></div>`:`<p class="practice-prompt">Answer out loud first. Reveal a short answer and a complete structured response, then compare the explanation and evidence with your own.</p><button class="button primary" data-action="reveal">Reveal the answer ↓</button>`}<div class="practice-footer"><button class="button subtle" data-action="open" data-id="${q.id}">Open full notes ↗</button><button class="button subtle" data-action="skip-practice">Skip this question →</button></div></article>`;
}
function formatTime(ms){const s=Math.floor(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
setInterval(()=>{if(practice&&!practice.revealed&&$('#practice-timer'))$('#practice-timer').textContent=formatTime(Date.now()-practice.start);},1000);
function glossary(){return `<div class="page-heading"><div class="eyebrow">Concepts & glossary</div><h1>Clear ideas. Precise language.</h1><p>A quick reference for the terms behind your methods, measurements and limitations. Search a term to connect it to answered interview questions.</p></div><div class="search-box"><span aria-hidden="true">⌕</span><input id="glossary-search" type="search" aria-label="Search concepts" placeholder="Find a concept, such as oracle or calibration…"></div><div id="glossary-results" class="glossary-grid"></div>`;}
function renderGlossary(){const term=$('#glossary-search').value.toLowerCase();const hits=data.glossary.filter(g=>`${g.term} ${g.definition}`.toLowerCase().includes(term));$('#glossary-results').innerHTML=hits.length?hits.map(g=>`<article class="glossary-card"><h3>${esc(g.term)}</h3><p>${esc(g.definition)}</p><a class="text-link" style="display:inline-block;margin-top:12px" href="#library?q=${encodeURIComponent(g.term.replace(/ \/ .*/,''))}">Explore in the questions ↗</a></article>`).join(''):'<div class="empty"><h3>No matching concepts.</h3><p>Try a shorter word or search the question library.</p></div>';}
function sourcesView(){return `<div class="page-heading"><div class="eyebrow">Sources & accuracy</div><h1>Know what the evidence supports.</h1><p>Each of the ${data.questions.length} questions has a complete, structured practice answer as well as a concise answer. Research findings retain their sources and limitations. Proposed plans use future-oriented wording, and questions for professors contain exact conversation scripts.</p></div><div class="info-strip"><strong>Status and study-pack check: 5 November 2026.</strong> XLAgent is under review; its experimental numbers use the strict 21 October working revision. Published results are historical findings, not current model rankings. The site contains paraphrased study notes, not full manuscripts.</div><div class="info-strip"><strong>Language review:</strong> The original 208 drafts received historical language review. The additional title, Evident, interview and research journey answers were written manually and checked against sources. Paraphrase scores are not evidence of factual quality.</div><div class="source-list">${data.sources.map(s=>`<article class="source-card"><span class="badge">${s.kind}</span><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p>${s.url?`<a href="${s.url}" target="_blank" rel="noopener noreferrer">Open reference ↗</a>`:''}</article>`).join('')}</div><section class="panel" style="margin-top:25px"><h2>Five distinctions to keep straight</h2>${table(['Distinction','Why it matters'],[['167 ICPC vs 367 total','The A-ProS 39 → 90 result is the ICPC subset.'],['More than 2× gain vs final accuracy','Gain uses the initial baseline; final-rate ratios are smaller.'],['Repeated verdict vs repeated root cause','Two Wrong Answers can have different semantic causes.'],['11 / 12 graph coverage vs all bugs','It is in-scope coverage; all indexed strict fixes are 13 / 30.'],['Two-sided edit vs correct repair','Touching both languages is not proof of correct interaction.']])}</section><section class="panel" style="margin-top:25px"><h2>Your private study data</h2><p>Stars, confidence ratings, notes and checklist progress are stored in this browser. They are never sent to a server. Export a backup before changing browsers or clearing site data. These notes are not part of the public repository.</p><div class="data-actions"><button class="button primary" data-action="export">Export study data ↓</button><button class="button" data-action="import">Import a backup ↑</button><input type="file" id="import-file" accept="application/json,.json" hidden><button class="button" data-action="clear-data">Clear local study data</button></div><p class="settings-note">${storageAvailable?'Browser storage is available.':'Browser storage is unavailable; notes last only for this open session.'} Every entry now includes a full answer. Use the short version for quick recall and the structured version for a detailed rehearsal.</p></section>`;}
function relatedQuestions(q){return data.questions.filter(x=>x.id!==q.id&&x.project===q.project).map(x=>({q:x,score:x.tags.filter(t=>t!=='essential'&&q.tags.includes(t)).length+(x.topic===q.topic ? 0.5 : 0)})).sort((a,b)=>b.score-a.score).slice(0,3).map(x=>x.q);}
function openQuestion(id){const q=data.questions.find(q=>q.id===id);if(!q){toast('That question could not be found.');location.hash='#library';return;}
 const s=data.sources.find(s=>s.id===q.source),saved=state.saved.includes(id),dialog=$('#question-dialog');document.title=`${q.question} · Research Interview Atlas`;
 $('#question-content').innerHTML=`<div class="dialog-head"><span>${esc(labels[q.project])} / ${esc(q.topic)}</span><button class="icon-button" data-action="close-dialog" aria-label="Close answer">×</button></div><article class="dialog-body"><div class="q-meta">${meta(q)}</div><h2 id="dialog-title">${esc(q.question)}</h2><details class="short-answer"><summary>${q.project==='ask'?'Main question at a glance':'Short answer for quick recall'}</summary><p class="spoken">${esc(q.answer)}</p></details><div class="answer-label">${q.project==='ask'?'Complete conversation script':'Complete practice answer'}</div><div class="full-answer">${answerSections(q)}</div>${q.caution?`<div class="caution"><strong>Scope & limitations</strong>${esc(q.caution)}</div>`:''}${followupMarkup(q)}<div class="answer-label">Source & evidence</div><p class="source-evidence"><span class="badge">${esc(s.kind)}</span><br>${s.url?`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}<br>${esc(q.locator)}</p><div class="answer-label">Your practice notes</div><textarea class="notes" id="question-notes" data-id="${id}" aria-label="Private notes for this question" placeholder="Add your rehearsal notes, examples, or follow-up details…">${esc(state.notes[id]||'')}</textarea><p class="footnote">Saved on this device. ${storageAvailable?'Export a backup from Sources & accuracy.':'Storage is unavailable; export before leaving.'}</p><div class="dialog-actions"><button class="button ${saved?'primary':''}" data-action="save" data-id="${id}">${saved?'★ Saved':'☆ Save question'}</button><button class="button" data-action="copy" data-id="${id}">Copy answer</button><button class="button" data-action="copy-link" data-id="${id}">Copy link ↗</button></div><div class="answer-label">Keep exploring</div><div class="essential-list">${relatedQuestions(q).map(essentialRow).join('')}</div></article>`;
 if(!dialog.open)dialog.showModal();else dialog.scrollTop=0;
}
const mobileMedia=matchMedia('(max-width:700px)');
function syncNavigation(){const hidden=mobileMedia.matches&&!document.body.classList.contains('menu-open');$('#sidebar').inert=hidden;$('#sidebar').setAttribute('aria-hidden',String(hidden));}
mobileMedia.addEventListener('change',syncNavigation);syncNavigation();
function setActive(view,id){$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===(id||view);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function render(){const raw=location.hash.slice(1)||'home';const [path,query='']=raw.split('?');const params=new URLSearchParams(query),[view,id]=path.split('/');
 if(view==='question'){if($('#main .loading')){$('#main').innerHTML=home();stats();setActive('home');}openQuestion(id);return;}
 const dialog=$('#question-dialog');if(dialog.open)dialog.close();currentView=view;lastPage=location.hash||'#home';document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');syncNavigation();
 setActive(view,view==='project'?id:view==='interview'?'pack-'+id:null);$('#breadcrumb').textContent=view==='interview'?(data.studyPacks?.find(p=>p.id===id)?.title||'Study pack'):view==='project'?`The research / ${labels[id]||'Project'}`:({home:'Your preparation space',library:'The question library',saved:'Your study collection',practice:'The practice room',journey:'Research journey',ask:'Ask the professor',glossary:'Concepts & glossary',sources:'Sources & accuracy'}[view]||'Your preparation space');
 let html;if(view==='home')html=home();else if(['library','saved','ask'].includes(view))html=library(view,params);else if(view==='interview')html=studyPackView(id);else if(view==='journey')html=journeyView(id);else if(view==='project')html=projectView(id);else if(view==='practice')html=practiceView();else if(view==='glossary')html=glossary();else if(view==='sources')html=sourcesView();else html='<div class="empty"><h3>This page could not be found.</h3><a class="button" href="#home">Return to overview</a></div>';
 $('#main').innerHTML=html;stats();if(['library','saved','ask'].includes(view))updateResults();if(view==='practice')renderPractice();if(view==='glossary')renderGlossary();if(view==='interview'){renderContextCase();renderPackQuestions();}document.title=`${$('#breadcrumb').textContent} · Research Interview Atlas`;window.scrollTo(0,0);
}
function closeDialog(){location.hash=lastPage;}
function toggleSave(id){if(state.saved.includes(id))state.saved=state.saved.filter(x=>x!==id);else state.saved.push(id);persist();stats();$$(`[data-action="save"][data-id="${id}"]`).forEach(b=>{const saved=state.saved.includes(id);b.classList.toggle('saved',saved);b.setAttribute('aria-pressed',saved);b.setAttribute('aria-label',`${saved?'Unsave':'Save'} question`);if(b.classList.contains('save-star'))b.textContent=saved?'★':'☆';else{b.textContent=saved?'★ Saved':'☆ Save question';b.classList.toggle('primary',saved);}});if(currentView==='saved'&&!$('#question-dialog').open)updateResults(false);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{toast('Clipboard access unavailable. Select and copy the text manually.');}}
document.addEventListener('click',async e=>{
 if(e.target.closest('a.skip')){e.preventDefault();$('#main').focus();return;}
 const target=e.target.closest('[data-action]');if(!target)return;const id=target.dataset.id;
 switch(target.dataset.action){
 case'open':location.hash=`#question/${id}`;break;
 case'close-dialog':closeDialog();break;
 case'save':toggleSave(id);break;
 case'speech':selectSpeech(id);break;
 case'clear-search':$('#library-search').value='';updateResults();$('#library-search').focus();break;
 case'reset-filters':location.hash=`#${currentView}`;if(location.hash===lastPage)render();break;
 case'more':limit+=30;updateResults(false);break;
 case'copy':{const q=data.questions.find(q=>q.id===id);await copy(`${q.question}\n\n${q.answer}\n\n${(q.answerSections||[]).map(section=>section.heading+'\n'+section.body).join('\n\n')}${q.caution?'\n\nScope & limitations: '+q.caution:''}\n\nSource: ${data.sources.find(s=>s.id===q.source).title}; ${q.locator}`);break;}
 case'copy-link':await copy(`${location.href.split('#')[0]}#question/${id}`);break;
 case'practice-pack':practice={project:'all',mode:'pack:'+target.dataset.pack,size:10};location.hash='#practice';break;
 case'jump-pack':$('#pack-questions')?.scrollIntoView({behavior:'smooth'});break;
 case'practice-project':practice={project:target.dataset.project,mode:'essential',size:10};location.hash='#practice';break;
 case'start-practice':startPractice();break;
 case'reveal':if(practice){practice.elapsed=Date.now()-practice.start;practice.revealed=true;renderPractice();}break;
 case'rate':if(practice){const q=practice.deck[practice.pos];state.ratings[q.id]=target.dataset.rating;persist();practice.results.push(target.dataset.rating);practice.pos++;practice.revealed=false;practice.start=Date.now();renderPractice();}break;
 case'skip-practice':if(practice){practice.results.push('skip');practice.pos++;practice.revealed=false;practice.start=Date.now();renderPractice();}break;
 case'export':{const blob=new Blob([JSON.stringify({format:KEY,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`interview-atlas-study-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Study data exported. Keep the file private.');break;}
 case'import':$('#import-file').click();break;
 case'clear-data':if(confirm('Clear all saved questions, private notes, ratings and checklist progress in this browser? Export a backup first if needed.')){state=defaults();persist();stats();toast('Local study data cleared.');render();}break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='library-search')updateResults();if(e.target.id==='glossary-search')renderGlossary();if(e.target.id==='pack-search')renderPackQuestions();if(e.target.id==='question-notes'){state.notes[e.target.dataset.id]=e.target.value;persist();}});
document.addEventListener('change',async e=>{
 if(e.target.id==='context-case')renderContextCase();
 if(e.target.matches('#project-filter')){const project=e.target.value;$('#topic-filter').innerHTML='<option value="all">All topics</option>'+[...new Set(data.questions.filter(q=>project==='all'||q.project===project).map(q=>q.topic))].sort().map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');updateResults();}
 if(e.target.matches('#topic-filter,#difficulty-filter,#essential-filter'))updateResults();
 if(e.target.dataset.check!==undefined){state.checklist[e.target.dataset.check]=e.target.checked;persist();}
 if(e.target.id==='import-file'){
  try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('File too large');const incoming=JSON.parse(await file.text());if(incoming.format!==KEY||!incoming.data||!Array.isArray(incoming.data.saved)||typeof incoming.data.notes!=='object'||incoming.data.notes===null)throw Error('Unsupported format');const clean=defaults(),known=new Set(data.questions.map(q=>q.id));clean.saved=incoming.data.saved.filter(id=>typeof id==='string'&&known.has(id));for(const [id,note] of Object.entries(incoming.data.notes))if(known.has(id)&&typeof note==='string')clean.notes[id]=note.slice(0,100000);for(const [id,rating] of Object.entries(incoming.data.ratings||{}))if(known.has(id)&&['again','confident'].includes(rating))clean.ratings[id]=rating;for(const [id,checked] of Object.entries(incoming.data.checklist||{}))if(/^[0-5]$/.test(id))clean.checklist[id]=checked===true;if(confirm('Replace local study data with this backup? Export your current data first if you want to keep it.')){state=clean;persist();stats();toast('Study data imported.');render();}}catch{toast('Could not import. Choose a valid Interview Atlas backup.');}finally{if($('#import-file'))$('#import-file').value='';}
 }
});
$('#question-dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#question-dialog').addEventListener('click',e=>{if(e.target===$('#question-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function focusSearch(){if($('#pack-search')&&!$('#question-dialog').open){$('#pack-search').focus();return;}if($('#question-dialog').open){$('#question-dialog').close();location.hash='#library';setTimeout(()=>$('#library-search')?.focus(),0);return;}if(!$('#library-search')){location.hash='#library';setTimeout(()=>$('#library-search')?.focus(),0);}else $('#library-search').focus();}
$('#search-shortcut').addEventListener('click',focusSearch);
$('#menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',open);$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');syncNavigation();});
document.addEventListener('keydown',e=>{if((e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))||((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k')){e.preventDefault();focusSearch();}if(e.key==='Escape'&&document.body.classList.contains('menu-open')){document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');syncNavigation();$('#menu-toggle').focus();}});
window.addEventListener('hashchange',render);
try{const response=await fetch('./data/content.json');if(!response.ok)throw Error('Content unavailable');data=await response.json();index=createIndex(data.questions,data.projects);render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(error){$('#main').innerHTML='<div class="empty"><h3>The guide could not load.</h3><p>Check your connection and reload. For local development, run npm run dev and open the printed URL.</p></div>';console.error(error);}
